import{_ as i,c as t,o as a,ae as n}from"./chunks/framework.DMK_uHmU.js";const d=JSON.parse('{"title":"AI Chat History Manager User Guide","description":"","frontmatter":{},"headers":[],"relativePath":"Assistant/chat-history.md","filePath":"Assistant/chat-history.md"}'),l={name:"Assistant/chat-history.md"};function o(r,e,s,h,c,u){return a(),t("div",null,e[0]||(e[0]=[n('<h1 id="ai-chat-history-manager-user-guide" tabindex="-1">AI Chat History Manager User Guide <a class="header-anchor" href="#ai-chat-history-manager-user-guide" aria-label="Permalink to &quot;AI Chat History Manager User Guide&quot;">​</a></h1><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="#ai-chat-history-manager-user-guide">AI Chat History Manager User Guide</a><ul><li><a href="#table-of-contents">Table of Contents</a></li><li><a href="#introduction">Introduction</a></li><li><a href="#accessing-chat-history">Accessing Chat History</a></li><li><a href="#chat-history-interface">Chat History Interface</a></li><li><a href="#managing-conversations">Managing Conversations</a><ul><li><a href="#creating-new-chats">Creating New Chats</a></li><li><a href="#selecting-existing-chats">Selecting Existing Chats</a></li><li><a href="#searching-chat-history">Searching Chat History</a></li><li><a href="#sorting-options">Sorting Options</a></li></ul></li><li><a href="#chat-actions">Chat Actions</a><ul><li><a href="#renaming-chats">Renaming Chats</a></li><li><a href="#adding-tags">Adding Tags</a></li><li><a href="#viewing-token-counts">Viewing Token Counts</a></li><li><a href="#clearing-conversations">Clearing Conversations</a></li><li><a href="#deleting-chats">Deleting Chats</a></li></ul></li><li><a href="#blueprint-management">Blueprint Management</a><ul><li><a href="#viewing-blueprints">Viewing Blueprints</a></li><li><a href="#using-blueprints">Using Blueprints</a></li><li><a href="#creating-blueprints">Creating Blueprints</a></li></ul></li><li><a href="#advanced-features">Advanced Features</a><ul><li><a href="#tag-visibility">Tag Visibility</a></li><li><a href="#refreshing-history">Refreshing History</a></li></ul></li><li><a href="#mobile-experience">Mobile Experience</a></li><li><a href="#troubleshooting">Troubleshooting</a></li></ul></li></ul><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>The AI Chat History Manager provides a comprehensive interface for organizing, searching, and managing your AI conversations. This sidebar allows you to access past conversations, create new chat sessions, work with AI Blueprints, and organize your AI interactions through tags and naming. This guide explains how to effectively use the Chat History Manager to maximize your AI assistant experience.</p><h2 id="accessing-chat-history" tabindex="-1">Accessing Chat History <a class="header-anchor" href="#accessing-chat-history" aria-label="Permalink to &quot;Accessing Chat History&quot;">​</a></h2><p>The Chat History Manager appears as a sidebar panel within the AI Assistant interface:</p><ol><li>Access by clicking the chat history icon in the main Assistant interface</li><li>The panel displays your conversation history and available Blueprints</li><li>History is organized chronologically with newest conversations at the top by default</li></ol><h2 id="chat-history-interface" tabindex="-1">Chat History Interface <a class="header-anchor" href="#chat-history-interface" aria-label="Permalink to &quot;Chat History Interface&quot;">​</a></h2><p>The Chat History Manager consists of two main sections:</p><ol><li><p><strong>Chat History Section</strong>:</p><ul><li>Search bar at the top for finding specific conversations</li><li>Sorting and display controls</li><li>List of past conversations with action menus</li><li>New chat creation button</li></ul></li><li><p><strong>Blueprints Section</strong> (when enabled):</p><ul><li>List of available AI Blueprints</li><li>Blueprint creation button</li><li>Blueprint action buttons</li></ul></li></ol><h2 id="managing-conversations" tabindex="-1">Managing Conversations <a class="header-anchor" href="#managing-conversations" aria-label="Permalink to &quot;Managing Conversations&quot;">​</a></h2><h3 id="creating-new-chats" tabindex="-1">Creating New Chats <a class="header-anchor" href="#creating-new-chats" aria-label="Permalink to &quot;Creating New Chats&quot;">​</a></h3><p>To start a fresh conversation:</p><ol><li>Click the &quot;+&quot; button in the top-right corner of the Chat History section</li><li>A new conversation appears at the top of your history list</li><li>The conversation initially uses the default date/time as its name</li><li>The AI Assistant interface resets to begin a new conversation</li></ol><p>You can also create new chats through keyboard shortcut Ctrl+N or from the main Assistant interface.</p><h3 id="selecting-existing-chats" tabindex="-1">Selecting Existing Chats <a class="header-anchor" href="#selecting-existing-chats" aria-label="Permalink to &quot;Selecting Existing Chats&quot;">​</a></h3><p>To resume a previous conversation:</p><ol><li>Locate the desired conversation in the history list</li><li>Click on the conversation name</li><li>The main Assistant interface loads the selected conversation</li><li>All previous messages and context are restored</li></ol><h3 id="searching-chat-history" tabindex="-1">Searching Chat History <a class="header-anchor" href="#searching-chat-history" aria-label="Permalink to &quot;Searching Chat History&quot;">​</a></h3><p>To find specific conversations:</p><ol><li>Type keywords in the search field at the top of the history panel</li><li>Search matches conversation names and tags</li><li>Results update in real-time as you type</li><li>The list filters to show only matching conversations</li></ol><h3 id="sorting-options" tabindex="-1">Sorting Options <a class="header-anchor" href="#sorting-options" aria-label="Permalink to &quot;Sorting Options&quot;">​</a></h3><p>Change the order of your conversation list:</p><ol><li><p>Click the sort icon (stack of lines) to open the sort menu</p></li><li><p>Choose from available sorting options:</p><ul><li><strong>Updated (New → Old)</strong>: Most recently active first (default)</li><li><strong>Updated (Old → New)</strong>: Oldest active first</li><li><strong>Alpha (A → Z)</strong>: Alphabetical by name</li><li><strong>Alpha (Z → A)</strong>: Reverse alphabetical</li><li><strong>Created (New → Old)</strong>: Newest created first</li><li><strong>Created (Old → New)</strong>: Oldest created first</li></ul></li><li><p>The selected sort is highlighted and applied immediately</p></li><li><p>The sort preference persists until changed</p></li></ol><h2 id="chat-actions" tabindex="-1">Chat Actions <a class="header-anchor" href="#chat-actions" aria-label="Permalink to &quot;Chat Actions&quot;">​</a></h2><h3 id="renaming-chats" tabindex="-1">Renaming Chats <a class="header-anchor" href="#renaming-chats" aria-label="Permalink to &quot;Renaming Chats&quot;">​</a></h3><p>To give your conversations meaningful names:</p><ol><li>Click the three-dot menu next to a conversation</li><li>Select &quot;Rename &amp; Tags&quot;</li><li>In the dialog that appears: <ul><li>Enter a new name in the &quot;Chat Name&quot; field</li><li>Click &quot;Save&quot; to apply the change</li></ul></li><li>The conversation appears with its new name in the list</li></ol><p>Newly created conversations start with a date/time name that you can customize for easier reference.</p><h3 id="adding-tags" tabindex="-1">Adding Tags <a class="header-anchor" href="#adding-tags" aria-label="Permalink to &quot;Adding Tags&quot;">​</a></h3><p>Tags help organize and find related conversations:</p><ol><li>Click the three-dot menu next to a conversation</li><li>Select &quot;Rename &amp; Tags&quot;</li><li>In the dialog that appears: <ul><li>Type a tag name and press Enter to add it</li><li>Click the X on any tag to remove it</li><li>Click &quot;Save&quot; to apply changes</li></ul></li><li>Tags appear below conversation names when tag display is enabled</li></ol><h3 id="viewing-token-counts" tabindex="-1">Viewing Token Counts <a class="header-anchor" href="#viewing-token-counts" aria-label="Permalink to &quot;Viewing Token Counts&quot;">​</a></h3><p>To see token usage statistics for a conversation:</p><ol><li>Click the three-dot menu next to a conversation</li><li>Select &quot;Token Count&quot;</li><li>A dialog appears showing: <ul><li>Total tokens used (input and output)</li><li>Number of requests made</li><li>Breakdown by model used</li><li>Charts visualizing usage patterns</li></ul></li><li>This helps track resource utilization</li></ol><h3 id="clearing-conversations" tabindex="-1">Clearing Conversations <a class="header-anchor" href="#clearing-conversations" aria-label="Permalink to &quot;Clearing Conversations&quot;">​</a></h3><p>To remove all messages from a conversation while keeping the chat:</p><ol><li>Click the three-dot menu next to a conversation</li><li>Select &quot;Clear Conversation&quot;</li><li>Confirm in the dialog that appears</li><li>The conversation remains in your history but all messages are removed</li><li>You can start fresh while maintaining the chat&#39;s name and tags</li></ol><h3 id="deleting-chats" tabindex="-1">Deleting Chats <a class="header-anchor" href="#deleting-chats" aria-label="Permalink to &quot;Deleting Chats&quot;">​</a></h3><p>To completely remove a conversation:</p><ol><li>Click the three-dot menu next to a conversation</li><li>Select &quot;Delete Chat&quot;</li><li>Confirm the deletion in the dialog that appears</li><li>The conversation is permanently removed from your history</li></ol><h2 id="blueprint-management" tabindex="-1">Blueprint Management <a class="header-anchor" href="#blueprint-management" aria-label="Permalink to &quot;Blueprint Management&quot;">​</a></h2><h3 id="viewing-blueprints" tabindex="-1">Viewing Blueprints <a class="header-anchor" href="#viewing-blueprints" aria-label="Permalink to &quot;Viewing Blueprints&quot;">​</a></h3><p>When Blueprints are enabled:</p><ol><li>The lower half of the sidebar shows available Blueprints</li><li>Each Blueprint displays its name</li><li>Tags appear when tag display is enabled</li><li>The currently active Blueprint is highlighted</li></ol><h3 id="using-blueprints" tabindex="-1">Using Blueprints <a class="header-anchor" href="#using-blueprints" aria-label="Permalink to &quot;Using Blueprints&quot;">​</a></h3><p>To switch to a Blueprint:</p><ol><li>Click on the Blueprint name in the list</li><li>The main Assistant interface loads the Blueprint</li><li>The Blueprint&#39;s settings, knowledge sources, and specialized capabilities become active</li><li>The conversation starts with the Blueprint&#39;s home screen</li></ol><h3 id="creating-blueprints" tabindex="-1">Creating Blueprints <a class="header-anchor" href="#creating-blueprints" aria-label="Permalink to &quot;Creating Blueprints&quot;">​</a></h3><p>To create a new Blueprint:</p><ol><li>Click the &quot;+&quot; button in the top-right corner of the Blueprints section</li><li>The Blueprint editor opens</li><li>Configure the Blueprint settings</li><li>Save to add it to your Blueprints list</li></ol><p>You can also edit existing Blueprints by clicking the pencil icon next to their name.</p><h2 id="advanced-features" tabindex="-1">Advanced Features <a class="header-anchor" href="#advanced-features" aria-label="Permalink to &quot;Advanced Features&quot;">​</a></h2><h3 id="tag-visibility" tabindex="-1">Tag Visibility <a class="header-anchor" href="#tag-visibility" aria-label="Permalink to &quot;Tag Visibility&quot;">​</a></h3><p>Control whether tags are visible in the history list:</p><ol><li>Click the tag icon in the button bar above the history list</li><li>When highlighted blue, tags are visible beneath each conversation name</li><li>When gray, tags are hidden to save space</li><li>Tags are still searchable even when not displayed</li></ol><h3 id="refreshing-history" tabindex="-1">Refreshing History <a class="header-anchor" href="#refreshing-history" aria-label="Permalink to &quot;Refreshing History&quot;">​</a></h3><p>To update the history list with the latest data:</p><ol><li>Click the refresh icon in the button bar</li><li>The system retrieves the latest conversation data</li><li>Useful after creating new conversations in other windows</li><li>A loading spinner appears during refresh</li></ol><h2 id="mobile-experience" tabindex="-1">Mobile Experience <a class="header-anchor" href="#mobile-experience" aria-label="Permalink to &quot;Mobile Experience&quot;">​</a></h2><p>When using the Chat History Manager on mobile devices:</p><ol><li>The interface adapts to fit smaller screens</li><li>Swipe gestures can be used for navigation</li><li>The Blueprint section may appear below the history section</li><li>Tap and hold replaces right-click for menu access</li><li>The search bar remains accessible at the top</li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Issue</strong>: Chat history not loading</p><ul><li>Click the refresh icon to reload data</li><li>Check your network connection</li><li>Verify you&#39;re signed in properly</li><li>If problems persist, try reloading the page</li></ul><p><strong>Issue</strong>: Cannot find specific conversations</p><ul><li>Try different search terms</li><li>Check if you&#39;re using the correct sorting order</li><li>Try showing tags if they might contain relevant keywords</li><li>Consider if the conversation might have been deleted</li></ul><p><strong>Issue</strong>: Cannot delete or clear conversations</p><ul><li>Ensure you&#39;re not trying to perform actions while the AI is busy responding</li><li>Check if you have proper permissions for the action</li><li>Try refreshing the history list</li><li>If an error appears, note the error message for support</li></ul><p><strong>Issue</strong>: Rename not appearing immediately</p><ul><li>Some name changes may take a moment to propagate</li><li>The &quot;Renaming...&quot; indicator shows when a rename is in progress</li><li>Try refreshing the history list if names aren&#39;t updating</li></ul><p><strong>Issue</strong>: Blueprint list not showing all Blueprints</p><ul><li>Click the refresh icon to reload Blueprints</li><li>Check if your search term might be filtering the list</li><li>Verify you have permissions to see all Blueprints</li><li>Some Blueprints may be restricted to certain users</li></ul><p><strong>Issue</strong>: Tags not appearing</p><ul><li>Ensure the tag visibility button is activated (blue)</li><li>Check if the conversation has any tags assigned</li><li>Try adding tags through the Rename &amp; Tags dialog</li></ul><hr><p>For additional assistance with the Chat History Manager, please contact your system administrator or refer to the platform documentation.</p>',78)]))}const p=i(l,[["render",o]]);export{d as __pageData,p as default};
